import logging
from ute_ue.utils.proxy_mngr import ProxiedCfgFileBasedUePool
from ute_ue.config import loggers as ta_ue_logging

from taf.ue.fastmile.ue import FastmileUe
from taf.ue.fastmile.exceptions import ReserveUeFailure

# TODO: What about moving it to versioning.py
# variables used to deploy proxy service via proxy mngr
MIN_REQUIRED_UEPROXY_VER = '1.11.0'
MIN_REQUIRED_ACCESS_VER = '1.6.4'


class TafUeFastmilePool(ProxiedCfgFileBasedUePool):

    def __init__(self, config_file_path=None, inline_config=None):
        """

        :param config_file_path:
        :param inline_config:
        """
        self.inline_config = inline_config
        super(TafUeFastmilePool, self).__init__(config_file_path, inline_config)
        self.rpc_clients = set()

        raw_logger = logging.getLogger("ute_ue")
        self.logger = ta_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'UEPOOL'})

    def create_device(self, device_name, device_config):
        """
        Create instance of ue

        :param device_name:
        :param device_config:
        :return: ue instance
        """
        self.logger.debug("executing create_device with name {} and configuration {}".format(device_name, device_config))
        constructor_parameters = device_config["CONSTRUCTOR_PARAMETERS"]
        ue_pc_address = constructor_parameters["configuration"]["ue_pc_address"]
        self.prepare_ueproxy_service(device_config)
        rpc_client = self.get_ueproxy_connection_client_by(ue_pc_address)
        self.rpc_clients.add(rpc_client)
        fastmile_ue = FastmileUe(name=device_name,
                                 ue_pc=rpc_client,
                                 configuration=constructor_parameters)
        is_reservation_successful = fastmile_ue.prepare_ue()
        if not is_reservation_successful:
            raise ReserveUeFailure("UE {} reservation failed".format(fastmile_ue.ue_id))
        return fastmile_ue

    def shutdown(self):
        """
        Shutdown

        avoid: RuntimeError: dictionary changed size during iteration
        """
        for rpc_client in self.rpc_clients:
            self.ueproxy_teardown(rpc_client)
